mapper.select:
select r.* from att_daily_result r

    and r.result_id=#{resultId}
    and r.employee_id=#{employeeId}
    and r.site_id=#{siteId}
    and r.attendance_date=#{attendanceDate}
    and r.attendance_date >= #{beginDate}
    and r.attendance_date <= #{endDate}
    and r.employee_no like concat('%',#{employeeNo},'%')
    and r.employee_name like concat('%',#{employeeName},'%')
    and r.result_status=#{resultStatus}
    and r.result_status in ('NORMAL','ABNORMAL')
    and (r.missing_in=1 or r.missing_out=1)

        and r.late_minutes > 0
        and r.early_minutes > 0
        and r.missing_in=1
        and r.missing_out=1

    ${params.dataScope}

order by r.attendance_date desc,r.result_id desc

select e.*,u.user_name,u.dept_id,d.dept_name,s.site_name
from att_employee e join sys_user u on u.user_id=e.user_id and u.del_flag='0'
join sys_dept d on d.dept_id=u.dept_id and d.del_flag='0'
join att_site s on s.site_id=e.site_id
where e.site_id=#{siteId} and e.hire_date <= #{attendanceDate}
  and e.employee_id=#{employeeId}
  and (e.leave_date is null or e.leave_date >= #{attendanceDate})
${params.dataScope}
order by e.employee_id limit 1001

select p.* from att_checkin_record p where p.employee_id=#{employeeId} and p.site_id=#{siteId}
and p.checkin_time >= #{from} and p.checkin_time < #{until} and p.checkin_time <= #{now}
and not exists (select 1 from att_daily_result used where used.employee_id=p.employee_id
    and used.result_id != #{resultId}
    and (used.in_record_id=p.record_id or used.out_record_id=p.record_id))
order by p.checkin_time,p.record_id
